import { InvalidDataError } from '@/lib/stats/invalid-data-error';

export const SIMULATED_ID_PREFIX = 'sim-';
export const VARIANTS = ['control', 'social_proof'] as const;
export type Variant = (typeof VARIANTS)[number];

export type SimulatedVisitor = {
    visitorId: string;
    variant: Variant;
    /** Seconds from first exposure to first signup click, or null if the visitor never clicked. */
    clickedAfterSeconds: number | null;
    signedUp: boolean;
};

export const SIMULATED_DISCLOSURE =
    'Every visitor in this file was generated by the StudyStreak traffic simulator. None are real students.';
export const TRACKED_EVENTS = ['$flag_exposure', 'signup_clicked', 'signed_up'] as const;
export type TrackedEvent = (typeof TRACKED_EVENTS)[number];

/** Events the simulator handed to the SDK, and those the events API confirmed with a 2xx response. */
export type EventDelivery = Record<TrackedEvent, { tracked: number; confirmed: number }>;

export type SimulationRun = {
    environmentName: string;
    featureName: string;
    visitorsRequested: number;
    signupRate: Record<Variant, number>;
    clickToSignupRate: number;
    medianClickSeconds: number;
    notEnrolled: number;
    assignmentFailures: number;
    eventDelivery: EventDelivery;
};

export type SimulatedDataset = {
    kind: 'simulated';
    environment: 'simulation';
    disclosure: string;
    seed: number;
    generatedAt: string;
    run: SimulationRun;
    visitors: SimulatedVisitor[];
};

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null;

function parseVisitor(raw: unknown, index: number): SimulatedVisitor {
    const where = `visitors[${index}]`;
    if (!isRecord(raw)) {
        throw new InvalidDataError(`${where} must be an object.`);
    }
    const { visitorId, variant, clickedAfterSeconds, signedUp } = raw;
    if (typeof visitorId !== 'string' || !visitorId.startsWith(SIMULATED_ID_PREFIX)) {
        throw new InvalidDataError(`${where}.visitorId must start with "${SIMULATED_ID_PREFIX}".`);
    }
    if (!VARIANTS.includes(variant as Variant)) {
        throw new InvalidDataError(`${where}.variant must be one of ${VARIANTS.join(', ')}.`);
    }
    if (
        clickedAfterSeconds !== null &&
        (typeof clickedAfterSeconds !== 'number' || !Number.isFinite(clickedAfterSeconds) || clickedAfterSeconds < 0)
    ) {
        throw new InvalidDataError(`${where}.clickedAfterSeconds must be null or a non-negative number.`);
    }
    if (typeof signedUp !== 'boolean') {
        throw new InvalidDataError(`${where}.signedUp must be a boolean.`);
    }
    // In the app a signup can only start from the CTA, so a signup without a click is impossible.
    if (signedUp && clickedAfterSeconds === null) {
        throw new InvalidDataError(`${where} signed up without clicking Sign Up.`);
    }
    return { visitorId, variant: variant as Variant, clickedAfterSeconds, signedUp };
}

const isCount = (value: unknown): value is number => Number.isSafeInteger(value) && (value as number) >= 0;
const isRate = (value: unknown): value is number => typeof value === 'number' && value >= 0 && value <= 1;

function parseRun(raw: unknown): SimulationRun {
    if (!isRecord(raw)) {
        throw new InvalidDataError('run must be an object.');
    }
    const { environmentName, featureName, visitorsRequested, signupRate, clickToSignupRate, medianClickSeconds } = raw;
    if (typeof environmentName !== 'string' || typeof featureName !== 'string') {
        throw new InvalidDataError('run.environmentName and run.featureName must be strings.');
    }
    if (!isCount(visitorsRequested) || !isCount(raw.notEnrolled) || !isCount(raw.assignmentFailures)) {
        throw new InvalidDataError('run visitor counts must be non-negative integers.');
    }
    if (!isRecord(signupRate) || !VARIANTS.every((variant) => isRate(signupRate[variant]))) {
        throw new InvalidDataError('run.signupRate must give a rate from 0 to 1 for each variant.');
    }
    if (!isRate(clickToSignupRate) || typeof medianClickSeconds !== 'number' || !(medianClickSeconds > 0)) {
        throw new InvalidDataError('run.clickToSignupRate and run.medianClickSeconds are invalid.');
    }
    const delivery = raw.eventDelivery;
    if (!isRecord(delivery)) {
        throw new InvalidDataError('run.eventDelivery must be an object.');
    }
    for (const event of TRACKED_EVENTS) {
        const counts = delivery[event];
        if (
            !isRecord(counts) ||
            !isCount(counts.tracked) ||
            !isCount(counts.confirmed) ||
            counts.confirmed > counts.tracked
        ) {
            throw new InvalidDataError(
                `run.eventDelivery.${event} must have confirmed <= tracked, both non-negative integers.`,
            );
        }
    }
    return {
        environmentName,
        featureName,
        visitorsRequested,
        signupRate: { control: signupRate.control as number, social_proof: signupRate.social_proof as number },
        clickToSignupRate,
        medianClickSeconds,
        notEnrolled: raw.notEnrolled as number,
        assignmentFailures: raw.assignmentFailures as number,
        eventDelivery: Object.fromEntries(
            TRACKED_EVENTS.map((event) => {
                const counts = delivery[event] as { tracked: number; confirmed: number };
                return [event, { tracked: counts.tracked, confirmed: counts.confirmed }];
            }),
        ) as EventDelivery,
    };
}

/** Validates untrusted JSON as a simulated dataset. Nothing is defaulted, corrected or dropped. */
export function parseSimulatedDataset(raw: unknown): SimulatedDataset {
    if (!isRecord(raw)) {
        throw new InvalidDataError('The dataset must be a JSON object.');
    }
    if (raw.kind !== 'simulated' || raw.environment !== 'simulation') {
        throw new InvalidDataError(
            'Only datasets marked kind "simulated" from the "simulation" environment are accepted.',
        );
    }
    if (typeof raw.disclosure !== 'string' || raw.disclosure.trim() === '') {
        throw new InvalidDataError('disclosure must state that the data is simulated.');
    }
    if (!Number.isSafeInteger(raw.seed)) {
        throw new InvalidDataError('seed must be an integer.');
    }
    if (typeof raw.generatedAt !== 'string' || Number.isNaN(Date.parse(raw.generatedAt))) {
        throw new InvalidDataError('generatedAt must be an ISO 8601 timestamp.');
    }
    if (!Array.isArray(raw.visitors)) {
        throw new InvalidDataError('visitors must be an array.');
    }
    const run = parseRun(raw.run);
    const visitors = raw.visitors.map(parseVisitor);
    const ids = new Set(visitors.map((visitor) => visitor.visitorId));
    if (ids.size !== visitors.length) {
        throw new InvalidDataError('visitorId values must be unique.');
    }
    if (visitors.length + run.notEnrolled + run.assignmentFailures !== run.visitorsRequested) {
        throw new InvalidDataError(
            'Visitors, unenrolled visitors and assignment failures must add up to run.visitorsRequested.',
        );
    }
    return {
        kind: 'simulated',
        environment: 'simulation',
        disclosure: raw.disclosure,
        seed: raw.seed as number,
        generatedAt: raw.generatedAt,
        run,
        visitors,
    };
}
